/// Strongly-typed analytics event with optional reader context.
///
/// Do not place raw child audio or speech transcripts in [metadata]. The
/// serializer defensively removes common raw-audio/transcript keys and binary
/// payload values before sending properties to the backend.
@immutable
class AnalyticsEvent {
  const AnalyticsEvent({
    required this.type,
    required this.occurredAt,
    this.userId,
    this.childProfileId,
    this.bookId,
    this.pageId,
    this.pageNumber,
    this.sessionId,
    this.metadata = const {},
  });

  final AnalyticsEventType type;
  final DateTime occurredAt;
  final String? userId;
  final String? childProfileId;
  final String? bookId;
  final String? pageId;
  final int? pageNumber;
  final String? sessionId;
  final AnalyticsMetadata metadata;

  AnalyticsEvent copyWith({
    AnalyticsEventType? type,
    DateTime? occurredAt,
    String? userId,
    String? childProfileId,
    String? bookId,
    String? pageId,
    int? pageNumber,
    String? sessionId,
    AnalyticsMetadata? metadata,
  }) {
    return AnalyticsEvent(
      type: type ?? this.type,
      occurredAt: occurredAt ?? this.occurredAt,
      userId: userId ?? this.userId,
      childProfileId: childProfileId ?? this.childProfileId,
      bookId: bookId ?? this.bookId,
      pageId: pageId ?? this.pageId,
      pageNumber: pageNumber ?? this.pageNumber,
      sessionId: sessionId ?? this.sessionId,
      metadata: metadata ?? this.metadata,
    );
  }

  Map<String, dynamic> toProperties() {
    final properties = <String, dynamic>{
      ...AnalyticsMetadataSanitizer.sanitize(metadata),
    };

    void addString(String key, String? value) {
      if (value != null && value.trim().isNotEmpty) {
        properties[key] = value;
      }
    }

    addString('userId', userId);
    addString('childProfileId', childProfileId);
    addString('bookId', bookId);
    addString('pageId', pageId);
    if (pageNumber != null) {
      properties['pageNumber'] = pageNumber;
    }
    addString('sessionId', sessionId);

    return properties;
  }

  Map<String, dynamic> toApiJson({required String childProfileId}) {
    final body = <String, dynamic>{
      'event': type.eventName,
      'childProfileId': childProfileId,
      'source': 'mobile',
      'occurredAt': occurredAt.toUtc().toIso8601String(),
      'properties': toProperties(),
    };

    if (sessionId != null && sessionId!.trim().isNotEmpty) {
      body['sessionId'] = sessionId;
    }

    // The backend column is BIGINT. Keep non-numeric/mobile-local IDs in
    // properties only so analytics failures never block the reader.
    if (_isPositiveIntegerString(bookId)) {
      body['bookId'] = bookId;
    }

    return body;
  }
}

/// Defensively strips raw child audio, binary payloads, and speech transcripts
/// from analytics metadata while keeping JSON-compatible scores and context.
class AnalyticsMetadataSanitizer {
  const AnalyticsMetadataSanitizer._();

  static const Set<String> _blockedNormalizedKeys = {
    'audio',
    'rawaudio',
    'audiobytes',
    'audioblob',
    'audiobase64',
    'audiodata',
    'audiosamples',
    'microphonebuffer',
    'recording',
    'recordingbytes',
    'recordingdata',
    'transcript',
    'recognizedtext',
    'recognizedwords',
    'spokenwords',
    'utterance',
    'speechtext',
  };

  static Map<String, dynamic> sanitize(Map<String, Object?> metadata) {
    final sanitized = <String, dynamic>{};
    for (final entry in metadata.entries) {
      final key = entry.key.trim();
      if (key.isEmpty || _isBlockedKey(key)) {
        continue;
      }

      final value = _sanitizeValue(entry.value);
      if (value != null) {
        sanitized[key] = value;
      }
    }
    return sanitized;
  }

  static bool _isBlockedKey(String key) {
    final normalized = key
        .replaceAll(RegExp(r'[^A-Za-z0-9]'), '')
        .toLowerCase();
    return _blockedNormalizedKeys.contains(normalized);
  }

  static dynamic _sanitizeValue(Object? value) {
    if (value == null || value is String || value is num || value is bool) {
      return value;
    }
    if (value is DateTime) {
      return value.toUtc().toIso8601String();
    }
    if (value is Uri) {
      return value.toString();
    }
    if (value is ByteBuffer || value is TypedData) {
      return null;
    }
    if (value is Map) {
      final sanitized = <String, dynamic>{};
      for (final entry in value.entries) {
        final key = entry.key.toString().trim();
        if (key.isEmpty || _isBlockedKey(key)) {
          continue;
        }
        final childValue = _sanitizeValue(entry.value as Object?);
        if (childValue != null) {
          sanitized[key] = childValue;
        }
      }
      return sanitized;
    }
    if (value is Iterable) {
      return value
          .map((item) => _sanitizeValue(item as Object?))
          .where((item) => item != null)
          .toList(growable: false);
    }

    return value.toString();
  }
}

abstract interface class AnalyticsTransport {
  Future<void> send(Map<String, dynamic> body, {String? accessToken});
}

class HttpAnalyticsTransport implements AnalyticsTransport {
  HttpAnalyticsTransport({
    required http.Client client,
    required String apiBaseUrl,
  }) : _client = client,
       _endpoint = _analyticsEndpoint(apiBaseUrl);

  final http.Client _client;
  final Uri _endpoint;

  @override
  Future<void> send(Map<String, dynamic> body, {String? accessToken}) async {
    final headers = <String, String>{
      'accept': 'application/json',
      'content-type': 'application/json',
      if (accessToken != null && accessToken.trim().isNotEmpty)
        'authorization': 'Bearer $accessToken',
    };

    final response = await _client.post(
      _endpoint,
      headers: headers,
      body: jsonEncode(body),
    );

    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw AnalyticsTransportException(
        'Analytics request failed with status ${response.statusCode}.',
        statusCode: response.statusCode,
      );
    }
  }

  static Uri _analyticsEndpoint(String apiBaseUrl) {
    final trimmed = apiBaseUrl.trim().replaceFirst(RegExp(r'/+$'), '');
    final base = trimmed.isEmpty ? 'https://storia.kids' : trimmed;
    return Uri.parse('$base/api/analytics/events');
  }
}

class AnalyticsTransportException implements Exception {
  const AnalyticsTransportException(this.message, {this.statusCode});

  final String message;
  final int? statusCode;

  @override
  String toString() => message;
}

class AnalyticsRepository {
  AnalyticsRepository({
    required AnalyticsTransport transport,
    AnalyticsClock? clock,
    AnalyticsStringResolver? currentUserId,
    AnalyticsStringResolver? currentAccessToken,
    AnalyticsStringResolver? currentChildProfileId,
  }) : _transport = transport,
       _clock = clock ?? DateTime.now,
       _currentUserId = currentUserId ?? _nullString,
       _currentAccessToken = currentAccessToken ?? _nullString,
       _currentChildProfileId = currentChildProfileId ?? _nullString;

  final AnalyticsTransport _transport;
  final AnalyticsClock _clock;
  final AnalyticsStringResolver _currentUserId;
  final AnalyticsStringResolver _currentAccessToken;
  final AnalyticsStringResolver _currentChildProfileId;

  Future<bool> track(
    AnalyticsEventType type, {
    String? childProfileId,
    String? userId,
    String? bookId,
    String? pageId,
    int? pageNumber,
    String? sessionId,
    AnalyticsMetadata metadata = const {},
    DateTime? occurredAt,
  }) async {
    try {
      return await trackEvent(
        AnalyticsEvent(
          type: type,
          occurredAt: occurredAt ?? _clock(),
          userId: userId,
          childProfileId: childProfileId,
          bookId: bookId,
          pageId: pageId,
          pageNumber: pageNumber,
          sessionId: sessionId,
          metadata: metadata,
        ),
      );
    } catch (error, stackTrace) {
      _logNonFatal('Failed to track ${type.eventName}: $error', stackTrace);
      return false;
    }
  }

  /// Sends an analytics event. Returns false on missing child context or
  /// analytics pipeline failures and never throws, so instrumentation is
  /// non-fatal for reader flows.
  Future<bool> trackEvent(AnalyticsEvent event) async {
    try {
      final childProfileId = _firstNonBlank(
        event.childProfileId,
        _currentChildProfileId(),
      );
      if (childProfileId == null) {
        _logNonFatal(
          'Skipped ${event.type.eventName}: missing childProfileId.',
        );
        return false;
      }

      final eventWithContext = event.copyWith(
        childProfileId: childProfileId,
        userId: _firstNonBlank(event.userId, _currentUserId()),
      );

      await _transport.send(
        eventWithContext.toApiJson(childProfileId: childProfileId),
        accessToken: _currentAccessToken(),
      );
      return true;
    } catch (error, stackTrace) {
      _logNonFatal(
        'Failed to track ${event.type.eventName}: $error',
        stackTrace,
      );
      return false;
    }
  }

  static String? _nullString() => null;

  static String? _firstNonBlank(String? first, String? second) {
    if (first != null && first.trim().isNotEmpty) {
      return first;
    }
    if (second != null && second.trim().isNotEmpty) {
      return second;
    }
    return null;
  }

  void _logNonFatal(String message, [StackTrace? stackTrace]) {
    assert(() {
      debugPrint('[AnalyticsRepository] $message');
      return true;
    }());
  }
}

bool _isPositiveIntegerString(String? value) {
  if (value == null) {
    return false;
  }
  final trimmed = value.trim();
  if (!RegExp(r'^\d+$').hasMatch(trimmed)) {
    return false;
  }
  return trimmed.contains(RegExp(r'[1-9]'));
}

import 'dart:async';
import 'dart:math';

import '../../../data/analytics_repository.dart';
import '../../../data/models.dart';

typedef ReaderSessionIdFactory = String Function();

/// Centralized analytics instrumentation for the reader runtime.
///
/// This class owns per-reading-session identity and de-duplication so widgets
/// can report high-level runtime actions without coupling rebuilds to analytics
/// calls. It intentionally stores only metadata/scores/indices; never raw child
/// audio or speech transcripts.
class ReaderAnalyticsTracker {
  ReaderAnalyticsTracker({
    required AnalyticsRepository analyticsRepository,
    ReaderSessionIdFactory? sessionIdFactory,
    DateTime Function()? clock,
  }) : _analyticsRepository = analyticsRepository,
       _sessionIdFactory = sessionIdFactory ?? _defaultSessionId,
       _clock = clock ?? DateTime.now;

  final AnalyticsRepository _analyticsRepository;
  final ReaderSessionIdFactory _sessionIdFactory;
  final DateTime Function() _clock;

  Book? _book;
  String? _sessionId;
  DateTime? _sessionStartedAt;
  int _activePageIndex = 0;
  bool _bookCompletedTracked = false;
  bool _sessionEnded = true;
  int _speechAttemptSequence = 0;
  final Set<int> _viewedPageIndices = <int>{};

  String? get sessionId => _sessionId;

  void startBook(Book book, {int initialPageIndex = 0}) {
    if (!_sessionEnded) {
      endSession(reason: 'restarted');
    }

    _book = book;
    _sessionId = _sessionIdFactory();
    _sessionStartedAt = _clock();
    _activePageIndex = _clampPageIndex(book, initialPageIndex);
    _bookCompletedTracked = false;
    _sessionEnded = false;
    _speechAttemptSequence = 0;
    _viewedPageIndices.clear();

    _track(
      AnalyticsEventType.readingSessionStarted,
      metadata: {
        'initialPageIndex': _activePageIndex,
        'pageCount': book.pages.length,
      },
    );
    _track(
      AnalyticsEventType.bookStarted,
      metadata: {
        'initialPageIndex': _activePageIndex,
        'pageCount': book.pages.length,
      },
    );
    recordPageViewed(_activePageIndex, source: 'initial');
  }

  void recordPageNavigation(int fromPageIndex, int toPageIndex) {
    final book = _book;
    if (book == null || fromPageIndex == toPageIndex) {
      return;
    }
    final fromPage = _pageAt(book, fromPageIndex);
    final toPage = _pageAt(book, toPageIndex);
    _track(
      AnalyticsEventType.pageInteracted,
      page: fromPage,
      metadata: {
        'interactionType': 'page_navigation',
        'fromPageIndex': fromPageIndex,
        'toPageIndex': toPageIndex,
        if (toPage != null) 'toPageId': toPage.id,
        if (toPage != null) 'toPageNumber': toPage.pageNumber,
      },
    );
  }

  void recordPageViewed(int pageIndex, {String source = 'navigation'}) {
    final book = _book;
    if (book == null || book.pages.isEmpty) {
      return;
    }

    final clampedIndex = _clampPageIndex(book, pageIndex);
    _activePageIndex = clampedIndex;
    _viewedPageIndices.add(clampedIndex);
    final page = _pageAt(book, clampedIndex);
    _track(
      AnalyticsEventType.pageViewed,
      page: page,
      metadata: {
        'pageIndex': clampedIndex,
        'source': source,
        'pageCount': book.pages.length,
      },
    );

    if (clampedIndex == book.pages.length - 1 && !_bookCompletedTracked) {
      _bookCompletedTracked = true;
      _track(
        AnalyticsEventType.bookCompleted,
        page: page,
        metadata: {
          'pageIndex': clampedIndex,
          'pageCount': book.pages.length,
          'viewedPageCount': _viewedPageIndices.length,
        },
      );
    }
  }

  void recordPageInteraction({
    required String interactionType,
    int? pageIndex,
    Map<String, Object?> metadata = const {},
  }) {
    final book = _book;
    if (book == null) {
      return;
    }
    final effectivePageIndex = pageIndex ?? _activePageIndex;
    _track(
      AnalyticsEventType.pageInteracted,
      page: _pageAt(book, effectivePageIndex),
      metadata: {
        'interactionType': interactionType,
        'pageIndex': effectivePageIndex,
        ...metadata,
      },
    );
  }

  void recordNarrationPlayed({int? pageIndex}) {
    recordPageInteraction(
      interactionType: 'narration_toggle',
      pageIndex: pageIndex,
    );
    _trackCurrentPage(
      AnalyticsEventType.narrationPlayed,
      pageIndex: pageIndex,
      metadata: {'pageIndex': pageIndex ?? _activePageIndex},
    );
  }

  void recordSoundscapePlayed({int? pageIndex}) {
    recordPageInteraction(
      interactionType: 'soundscape_toggle',
      pageIndex: pageIndex,
    );
    _trackCurrentPage(
      AnalyticsEventType.soundscapePlayed,
      pageIndex: pageIndex,
      metadata: {'pageIndex': pageIndex ?? _activePageIndex},
    );
  }

  void recordWordAudioPlayed({
    required int wordIndex,
    required String outcome,
    int? pageIndex,
  }) {
    recordPageInteraction(
      interactionType: 'word_tap',
      pageIndex: pageIndex,
      metadata: {'wordIndex': wordIndex},
    );
    _trackCurrentPage(
      AnalyticsEventType.wordAudioPlayed,
      pageIndex: pageIndex,
      metadata: {'wordIndex': wordIndex, 'outcome': outcome},
    );
  }

  void recordPhonemeAudioPlayed({
    required int wordIndex,
    required String outcome,
    int? pageIndex,
  }) {
    recordPageInteraction(
      interactionType: 'word_long_press',
      pageIndex: pageIndex,
      metadata: {'wordIndex': wordIndex},
    );
    _trackCurrentPage(
      AnalyticsEventType.phonemeAudioPlayed,
      pageIndex: pageIndex,
      metadata: {'wordIndex': wordIndex, 'outcome': outcome},
    );
  }

  String? recordSpeechAttemptStarted({int? pageIndex}) {
    final book = _book;
    final sessionId = _sessionId;
    if (book == null || sessionId == null || _sessionEnded) {
      return null;
    }

    final attemptId = '$sessionId-speech-${++_speechAttemptSequence}';
    _trackCurrentPage(
      AnalyticsEventType.speechAttemptStarted,
      pageIndex: pageIndex,
      metadata: {
        'attemptId': attemptId,
        'pageIndex': pageIndex ?? _activePageIndex,
      },
    );
    return attemptId;
  }

  void recordSpeechAttemptCompleted({
    required String? attemptId,
    required String reason,
    required int matchedWordCount,
    required bool hadSpeech,
    int? pageIndex,
  }) {
    if (attemptId == null) {
      return;
    }
    _trackCurrentPage(
      AnalyticsEventType.speechAttemptCompleted,
      pageIndex: pageIndex,
      metadata: {
        'attemptId': attemptId,
        'reason': reason,
        'matchedWordCount': matchedWordCount,
        'hadSpeech': hadSpeech,
      },
    );
  }

  void endSession({String reason = 'dispose'}) {
    final book = _book;
    final sessionId = _sessionId;
    if (book == null || sessionId == null || _sessionEnded) {
      return;
    }

    final startedAt = _sessionStartedAt;
    final durationMs = startedAt == null
        ? null
        : _clock().difference(startedAt).inMilliseconds;
    final eventType = _bookCompletedTracked
        ? AnalyticsEventType.readingSessionEnded
        : AnalyticsEventType.readingSessionDropOff;

    _track(
      eventType,
      page: _pageAt(book, _activePageIndex),
      metadata: {
        'reason': reason,
        'completed': _bookCompletedTracked,
        'lastPageIndex': _activePageIndex,
        'pageCount': book.pages.length,
        'viewedPageCount': _viewedPageIndices.length,
        if (durationMs != null) 'durationMs': durationMs,
      },
    );

    _sessionEnded = true;
  }

  void _trackCurrentPage(
    AnalyticsEventType eventType, {
    int? pageIndex,
    Map<String, Object?> metadata = const {},
  }) {
    final book = _book;
    if (book == null) {
      return;
    }
    _track(
      eventType,
      page: _pageAt(book, pageIndex ?? _activePageIndex),
      metadata: metadata,
    );
  }

  void _track(
    AnalyticsEventType eventType, {
    PageData? page,
    Map<String, Object?> metadata = const {},
  }) {
    final book = _book;
    final sessionId = _sessionId;
    if (book == null || sessionId == null) {
      return;
    }

    try {
      unawaited(
        _analyticsRepository
            .track(
              eventType,
              bookId: book.id,
              pageId: page?.id,
              pageNumber: page?.pageNumber,
              sessionId: sessionId,
              metadata: metadata,
            )
            .catchError((Object _) => false),
      );
    } catch (_) {
      // Analytics must never interrupt reader interactions.
    }
  }

  static int _clampPageIndex(Book book, int pageIndex) {
    if (book.pages.isEmpty) {
      return 0;
    }
    return pageIndex.clamp(0, book.pages.length - 1);
  }

  static PageData? _pageAt(Book book, int pageIndex) {
    if (book.pages.isEmpty) {
      return null;
    }
    return book.pages[_clampPageIndex(book, pageIndex)];
  }

  static String _defaultSessionId() {
    final timestamp = DateTime.now().toUtc().microsecondsSinceEpoch;
    final entropy = Random.secure().nextInt(1 << 32).toRadixString(16);
    return 'reader-$timestamp-$entropy';
  }
}

import 'dart:async';

import 'package:flutter_test/flutter_test.dart';

import 'package:storia_kids/src/data/analytics_repository.dart';
import 'package:storia_kids/src/data/models.dart';
import 'package:storia_kids/src/features/reader/runtime/ports/audio_port.dart';
import 'package:storia_kids/src/features/reader/runtime/ports/scheduler_port.dart';
import 'package:storia_kids/src/features/reader/runtime/ports/speech_practice_port.dart';
import 'package:storia_kids/src/features/reader/runtime/reader_analytics_tracker.dart';
import 'package:storia_kids/src/features/reader/runtime/reader_intent.dart';
import 'package:storia_kids/src/features/reader/runtime/reader_session_impl.dart';

void main() {
  group('ReaderSessionImpl analytics instrumentation', () {
    late _FakeAnalyticsTransport transport;
    late ReaderAnalyticsTracker tracker;
    late _FakeAudioPort audio;
    late _FakeSpeechPracticePort speech;
    late ReaderSessionImpl session;

    setUp(() {
      transport = _FakeAnalyticsTransport();
      tracker = ReaderAnalyticsTracker(
        analyticsRepository: AnalyticsRepository(
          transport: transport,
          currentChildProfileId: () => 'child-1',
        ),
        sessionIdFactory: () => 'reader-session-1',
        clock: () => DateTime.utc(2026, 1, 1),
      );
      audio = _FakeAudioPort();
      speech = _FakeSpeechPracticePort();
      session = ReaderSessionImpl(
        audioPort: audio,
        speechPort: speech,
        scheduler: _FakeSchedulerPort(),
        analyticsTracker: tracker,
      );
    });

    tearDown(() async {
      await session.dispose();
    });

    test('tracks reader lifecycle, page, audio, and speech events', () async {
      await session.dispatch(ReaderStart(book: _book));
      await pumpEventQueue();

      expect(transport.events.map(_eventName), [
        'reading_session_started',
        'book_started',
        'page_viewed',
      ]);
      expect(transport.events.first['sessionId'], 'reader-session-1');
      expect(transport.events.first['childProfileId'], 'child-1');

      transport.events.clear();
      await session.dispatch(const ReaderGoToPage(1));
      await pumpEventQueue();

      expect(transport.events.map(_eventName), [
        'page_interacted',
        'page_viewed',
        'book_completed',
      ]);
      expect(
        _properties(transport.events[0])['interactionType'],
        'page_navigation',
      );
      expect(_properties(transport.events[1])['pageId'], 'page-2');

      transport.events.clear();
      await session.dispatch(const ReaderToggleNarration());
      await session.dispatch(const ReaderToggleSoundscape());
      await pumpEventQueue();

      expect(transport.events.map(_eventName), [
        'page_interacted',
        'narration_played',
        'page_interacted',
        'soundscape_played',
      ]);

      transport.events.clear();
      await session.dispatch(const ReaderPracticePrimaryAction());
      await pumpEventQueue();
      speech.emitResult('goodbye', isFinal: true);
      await pumpEventQueue();

      expect(transport.events.map(_eventName), [
        'speech_attempt_started',
        'speech_attempt_completed',
      ]);
      final completedProperties = _properties(transport.events.last);
      expect(completedProperties['matchedWordCount'], 1);
      expect(completedProperties['hadSpeech'], true);
      expect(completedProperties.containsKey('recognizedWords'), false);
      expect(completedProperties.containsKey('transcript'), false);

      transport.events.clear();
      await session.dispatch(const ReaderEnd(reason: 'test_end'));
      await pumpEventQueue();

      expect(transport.events.map(_eventName), ['reading_session_ended']);
      expect(_properties(transport.events.single)['completed'], true);
    });

    test('tracks runtime end as drop-off before book completion', () async {
      await session.dispatch(ReaderStart(book: _book));
      await pumpEventQueue();

      transport.events.clear();
      await session.dispatch(const ReaderEnd(reason: 'closed_early'));
      await pumpEventQueue();

      expect(transport.events.map(_eventName), ['reading_session_drop_off']);
      expect(_properties(transport.events.single)['reason'], 'closed_early');
      expect(_properties(transport.events.single)['completed'], false);
    });

    test(
      'tracks word and phoneme playback without raw word metadata',
      () async {
        tracker.startBook(_book);
        await pumpEventQueue();

        transport.events.clear();
        tracker.recordWordAudioPlayed(wordIndex: 3, outcome: 'fallback');
        tracker.recordPhonemeAudioPlayed(wordIndex: 4, outcome: 'played');
        await pumpEventQueue();

        expect(transport.events.map(_eventName), [
          'page_interacted',
          'word_audio_played',
          'page_interacted',
          'phoneme_audio_played',
        ]);
        for (final event in transport.events) {
          final properties = _properties(event);
          expect(properties.containsKey('word'), false);
          expect(properties.containsKey('spokenWords'), false);
          expect(properties.containsKey('transcript'), false);
        }
      },
    );

    test(
      'does not duplicate played events for rapid play-stop toggles',
      () async {
        await session.dispatch(ReaderStart(book: _book));
        await pumpEventQueue();

        transport.events.clear();
        await session.dispatch(const ReaderToggleNarration());
        await session.dispatch(const ReaderToggleNarration());
        await pumpEventQueue();

        expect(transport.events.map(_eventName), [
          'page_interacted',
          'narration_played',
        ]);

        transport.events.clear();
        await session.dispatch(const ReaderToggleSoundscape());
        await session.dispatch(const ReaderToggleSoundscape());
        await pumpEventQueue();

        expect(transport.events.map(_eventName), [
          'page_interacted',
          'soundscape_played',
        ]);
      },
    );

    test('analytics transport failures do not break reader flow', () async {
      transport.error = StateError('network');

      await expectLater(session.dispatch(ReaderStart(book: _book)), completes);
      await pumpEventQueue();
      var state = await session.states.first;
      expect(state.isReady, true);
      expect(state.activePageIndex, 0);

      await expectLater(session.dispatch(const ReaderGoToPage(1)), completes);
      await pumpEventQueue();
      state = await session.states.first;
      expect(state.activePageIndex, 1);
      expect(transport.events, isEmpty);
    });
  });
}

String _eventName(Map<String, dynamic> body) => body['event'] as String;

Map<String, dynamic> _properties(Map<String, dynamic> body) =>
    body['properties'] as Map<String, dynamic>;

final _book = Book(
  id: 'book-1',
  title: 'Test Book',
  pageCount: 2,
  pages: const [
    PageData(
      id: 'page-1',
      pageNumber: 1,
      textContent: 'hello world',
      narrationUrl: 'https://cdn/narration-1.mp3',
      soundscapeUrl: 'https://cdn/soundscape-1.mp3',
    ),
    PageData(
      id: 'page-2',
      pageNumber: 2,
      textContent: 'goodbye world',
      narrationUrl: 'https://cdn/narration-2.mp3',
      soundscapeUrl: 'https://cdn/soundscape-2.mp3',
    ),
  ],
);

class _FakeAnalyticsTransport implements AnalyticsTransport {
  final events = <Map<String, dynamic>>[];
  Object? error;

  @override
  Future<void> send(Map<String, dynamic> body, {String? accessToken}) async {
    final error = this.error;
    if (error != null) {
      throw error;
    }
    events.add(Map<String, dynamic>.from(body));
  }
}

class _FakeAudioPort implements AudioPort {
  final _narrationPosition = StreamController<Duration>.broadcast();
  final _narrationPlaying = StreamController<bool>.broadcast();
  final _soundscapePlaying = StreamController<bool>.broadcast();
  bool isNarrationPlaying = false;
  bool isSoundscapePlaying = false;

  @override
  Stream<Duration> get narrationPosition => _narrationPosition.stream;

  @override
  Stream<bool> get narrationPlaying => _narrationPlaying.stream;

  @override
  Stream<bool> get soundscapePlaying => _soundscapePlaying.stream;

  @override
  Future<void> ensureInitialized() async {}

  @override
  Future<void> loadPage(PageData page) async {}

  @override
  Future<void> transitionToPage(PageData page) async {}

  @override
  Future<void> toggleNarration() async {
    isNarrationPlaying = !isNarrationPlaying;
    _narrationPlaying.add(isNarrationPlaying);
  }

  @override
  Future<void> toggleSoundscape() async {
    isSoundscapePlaying = !isSoundscapePlaying;
    _soundscapePlaying.add(isSoundscapePlaying);
  }

  @override
  Future<void> setNarrationVolume(double volume) async {}

  @override
  Future<void> setSoundscapeVolume(double volume) async {}

  @override
  Future<void> dispose() async {
    await _narrationPosition.close();
    await _narrationPlaying.close();
    await _soundscapePlaying.close();
  }
}

class _FakeSpeechPracticePort implements SpeechPracticePort {
  void Function(String recognizedWords, {required bool isFinal})? _onResult;

  @override
  Future<bool> initialize() async => true;

  @override
  Future<void> startListening({
    required void Function(String recognizedWords, {required bool isFinal})
    onResult,
    required void Function() onDone,
    required void Function(Object error) onError,
  }) async {
    _onResult = onResult;
  }

  void emitResult(String recognizedWords, {required bool isFinal}) {
    _onResult?.call(recognizedWords, isFinal: isFinal);
  }

  @override
  Future<void> stopListening() async {}

  @override
  Future<void> dispose() async {
    _onResult = null;
  }
}

class _FakeSchedulerPort implements SchedulerPort {
  @override
  CancelableTask schedule(Duration delay, void Function() action) {
    return _FakeCancelableTask();
  }
}

class _FakeCancelableTask implements CancelableTask {
  @override
  void cancel() {}
}

