import { Prisma } from "@prisma/client";
import { NextRequest, NextResponse } from "next/server";
import { validateChildAccess } from "@/lib/child-auth";
import { prisma } from "@/lib/prisma";

function parsePositiveBigInt(value: unknown): bigint | null {
  if (typeof value !== "string" && typeof value !== "number" && typeof value !== "bigint") {
    return null;
  }

  const stringValue = String(value).trim();
  if (!/^\d+$/.test(stringValue)) {
    return null;
  }

  const parsed = BigInt(stringValue);
  return parsed > 0n ? parsed : null;
}

function invalidRequest(message: string, field: string) {
  return NextResponse.json(
    { error: { code: "invalid_request", message, details: { field } } },
    { status: 400 }
  );
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const event = typeof body?.event === "string" ? body.event.trim() : "";
    const childProfileId = typeof body?.childProfileId === "string" ? body.childProfileId.trim() : "";
    const source = typeof body?.source === "string" && body.source.trim() ? body.source.trim() : "mobile";
    const sessionId = typeof body?.sessionId === "string" && body.sessionId.trim() ? body.sessionId.trim() : null;
    const occurredAtRaw = body?.occurredAt;
    const properties = body?.properties;

    if (!event) {
      return invalidRequest("event is required", "event");
    }
    if (!childProfileId) {
      return invalidRequest("childProfileId is required", "childProfileId");
    }
    if (body?.bookId != null && parsePositiveBigInt(body.bookId) == null) {
      return invalidRequest("bookId must be a positive integer", "bookId");
    }
    if (properties != null && (typeof properties !== "object" || Array.isArray(properties))) {
      return invalidRequest("properties must be a JSON object", "properties");
    }

    const accessResult = await validateChildAccess(childProfileId);
    if ("error" in accessResult) return accessResult.error;

    const occurredAt =
      typeof occurredAtRaw === "string" || occurredAtRaw instanceof Date
        ? new Date(occurredAtRaw)
        : new Date();
    if (Number.isNaN(occurredAt.getTime())) {
      return invalidRequest("occurredAt must be a valid ISO date", "occurredAt");
    }

    const bookId = body?.bookId == null ? null : parsePositiveBigInt(body.bookId);
    const normalizedProperties = (properties ?? {}) as Prisma.InputJsonValue;

    await prisma.mobile_analytics_events.create({
      data: {
        id: crypto.randomUUID(),
        user_id: accessResult.user.id,
        child_profile_id: childProfileId,
        book_id: bookId,
        session_id: sessionId,
        event_name: event,
        source,
        properties: normalizedProperties,
        occurred_at: occurredAt,
      },
    });

    return NextResponse.json({ ok: true }, { status: 201 });
  } catch (error) {
    console.error("Failed to persist analytics event:", error);
    return NextResponse.json(
      { error: { code: "internal_error", message: "Failed to persist analytics event" } },
      { status: 500 }
    );
  }
}

import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:http/http.dart' as http;
import 'package:supabase_flutter/supabase_flutter.dart';

import 'analytics_repository.dart';
import 'book_repository.dart';
import 'models.dart';
import 'pronunciation_models.dart';
import 'pronunciation_repository.dart';

final supabaseClientProvider = Provider<SupabaseClient>((ref) {
  return Supabase.instance.client;
});

final apiBaseUrlProvider = Provider<String>((ref) {
  return dotenv.env['API_BASE_URL'] ?? 'https://storia.kids';
});

/// Current child profile used by backend analytics routes.
///
/// The mobile app does not yet have an active child-profile repository, so this
/// intentionally defaults to null. Feature screens can pass childProfileId
/// directly to AnalyticsRepository.track, and a future child-profile data layer
/// can override this provider globally.
final currentChildProfileIdProvider = Provider<String?>((ref) => null);

final analyticsHttpClientProvider = Provider<http.Client>((ref) {
  final client = http.Client();
  ref.onDispose(client.close);
  return client;
});

final analyticsTransportProvider = Provider<AnalyticsTransport>((ref) {
  return HttpAnalyticsTransport(
    client: ref.watch(analyticsHttpClientProvider),
    apiBaseUrl: ref.watch(apiBaseUrlProvider),
  );
});

final analyticsRepositoryProvider = Provider<AnalyticsRepository>((ref) {
  final supabase = ref.watch(supabaseClientProvider);
  return AnalyticsRepository(
    transport: ref.watch(analyticsTransportProvider),
    currentUserId: () => supabase.auth.currentSession?.user.id,
    currentAccessToken: () => supabase.auth.currentSession?.accessToken,
    currentChildProfileId: () => ref.read(currentChildProfileIdProvider),
  );
});

final bookRepositoryProvider = Provider<BookRepository>((ref) {
  final supabase = ref.watch(supabaseClientProvider);
  return BookRepository(supabase);
});

final bookLibraryProvider = FutureProvider<List<Book>>((ref) async {
  final repo = ref.watch(bookRepositoryProvider);
  return repo.getPublishedBooks();
});
final currentBookProvider = FutureProvider.family<Book?, String>((
  ref,
  bookId,
) async {
  if (bookId.isEmpty) {
    return null;
  }
  final repo = ref.watch(bookRepositoryProvider);
  return repo.getBookById(bookId);
});

final pronunciationRepositoryProvider = Provider<PronunciationRepository>((
  ref,
) {
  final supabase = ref.watch(supabaseClientProvider);
  return PronunciationRepository(supabase);
});

final bookManifestProvider =
    FutureProvider.family<BookPronunciationManifest?, String>((
      ref,
      bookId,
    ) async {
      if (bookId.isEmpty) {
        return null;
      }
      final repo = ref.watch(pronunciationRepositoryProvider);
      return repo.getManifestForBook(bookId);
    });

import 'package:flutter/material.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import 'src/app.dart';
import 'src/core/resilient_cache_manager.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await dotenv.load(fileName: '.env');

  await Supabase.initialize(
    url: dotenv.env['SUPABASE_URL'] ?? '',
    anonKey: dotenv.env['SUPABASE_ANON_KEY'] ?? '',
    authOptions: const FlutterAuthClientOptions(),
  );

  // Eagerly initialise the image cache manager so stale SQLite lock files
  // are cleaned up before any widget tries to load a cached image.
  await ResilientCacheManager.getInstance();

  runApp(const ProviderScope(child: StoriaApp()));
}

import 'dart:convert';
import 'dart:math';

import 'package:crypto/crypto.dart';
import 'package:sign_in_with_apple/sign_in_with_apple.dart';
import 'package:supabase_flutter/supabase_flutter.dart' as supabase;

class AppAuthException implements Exception {
  const AppAuthException(this.message);

  final String message;

  @override
  String toString() => message;
}

class AuthRepository {
  AuthRepository(this._client);

  final supabase.SupabaseClient _client;

  static const _callbackScheme = 'storia';
  static const _callbackHost = 'login-callback';
  static const _callbackUrl = '$_callbackScheme://$_callbackHost/';

  supabase.Session? get currentSession => _client.auth.currentSession;

  Stream<supabase.AuthState> get authStateChanges =>
      _client.auth.onAuthStateChange;

  Future<void> sendMagicLink({
    required String email,
    required bool shouldCreateUser,
  }) async {
    try {
      await _client.auth.signInWithOtp(
        email: email,
        emailRedirectTo: _callbackUrl,
        shouldCreateUser: shouldCreateUser,
      );
    } catch (error) {
      if (error is supabase.AuthException) {
        throw AppAuthException(error.message);
      }
      throw AppAuthException(
        _messageFrom(error, 'Could not send a magic link right now.'),
      );
    }
  }

  Future<void> signOut() async {
    try {
      await _client.auth.signOut();
    } catch (error) {
      if (error is supabase.AuthException) {
        throw AppAuthException(error.message);
      }
      throw AppAuthException(_messageFrom(error, 'Could not sign out.'));
    }
  }

  Future<bool> signInWithOAuth(supabase.OAuthProvider provider) async {
    try {
      return await _client.auth.signInWithOAuth(
        provider,
        redirectTo: _callbackUrl,
      );
    } catch (error) {
      if (error is supabase.AuthException) {
        throw AppAuthException(error.message);
      }
      throw AppAuthException(
        _messageFrom(error, 'Could not start the social sign-in flow.'),
      );
    }
  }

  Future<void> signInWithNativeApple() async {
    try {
      final rawNonce = _generateRawNonce();
      final hashedNonce = _sha256OfString(rawNonce);
      final credential = await SignInWithApple.getAppleIDCredential(
        scopes: const [
          AppleIDAuthorizationScopes.email,
          AppleIDAuthorizationScopes.fullName,
        ],
        nonce: hashedNonce,
      );

      final idToken = credential.identityToken;
      if (idToken == null || idToken.isEmpty) {
        throw const AppAuthException(
          'Could not get an Apple identity token from this device.',
        );
      }

      await _client.auth.signInWithIdToken(
        provider: supabase.OAuthProvider.apple,
        idToken: idToken,
        nonce: rawNonce,
      );
    } on SignInWithAppleAuthorizationException catch (error) {
      switch (error.code) {
        case AuthorizationErrorCode.canceled:
          throw const AppAuthException('Apple sign-in was canceled.');
        case AuthorizationErrorCode.failed:
        case AuthorizationErrorCode.notHandled:
          throw const AppAuthException(
            'Apple sign-in failed. Verify Sign in with Apple is enabled for this app and that this device is signed into an Apple ID.',
          );
        case AuthorizationErrorCode.invalidResponse:
          throw const AppAuthException(
            'Apple returned an invalid auth response. Please try again.',
          );
        case AuthorizationErrorCode.notInteractive:
          throw const AppAuthException(
            'Apple sign-in is not interactive right now. Try again when the app is active.',
          );
        case AuthorizationErrorCode.unknown:
          throw AppAuthException(
            _messageFrom(error, 'Could not complete Apple sign-in right now.'),
          );
      }
    } catch (error) {
      if (error is supabase.AuthException) {
        throw AppAuthException(error.message);
      }
      if (error is AppAuthException) {
        rethrow;
      }
      throw AppAuthException(
        _messageFrom(error, 'Could not complete Apple sign-in right now.'),
      );
    }
  }

  String _messageFrom(dynamic error, String fallback) {
    final message = error?.message;
    if (message is String && message.isNotEmpty) {
      return message;
    }
    return fallback;
  }

  String _generateRawNonce([int length = 32]) {
    const charset =
        '0123456789ABCDEFGHIJKLMNOPQRSTUVXYZabcdefghijklmnopqrstuvwxyz-._';
    final random = Random.secure();
    return List<String>.generate(
      length,
      (_) => charset[random.nextInt(charset.length)],
    ).join();
  }

  String _sha256OfString(String input) {
    final bytes = utf8.encode(input);
    final digest = sha256.convert(bytes);
    return digest.toString();
  }
}

import { NextResponse } from "next/server";
import { headers } from "next/headers";
import { createClient, SupabaseClient } from "@supabase/supabase-js";
import { prisma } from "@/lib/prisma";

const SUPABASE_URL =
  process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || "";
const SUPABASE_SERVICE_ROLE_KEY =
  process.env.SUPABASE_SERVICE_ROLE_KEY ||
  process.env.NEXT_PUBLIC_SUPABASE_SERVICE_ROLE_KEY ||
  "";

let supabaseAdmin: SupabaseClient | null = null;
function getSupabaseAdmin(): SupabaseClient {
  if (supabaseAdmin) return supabaseAdmin;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error(
      "Missing SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY for Supabase auth verification"
    );
  }
  supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
    auth: { autoRefreshToken: false, persistSession: false },
  });
  return supabaseAdmin;
}

export interface AuthenticatedUser {
  id: string;
  email: string;
  name: string;
  role: string;
}

function unauthorized(reason?: string) {
  if (reason) console.warn(`[child-auth] unauthorized: ${reason}`);
  return NextResponse.json(
    { error: { code: "unauthorized", message: "Authentication required" } },
    { status: 401 }
  );
}

function extractBearer(raw: string | null): string | null {
  if (!raw) return null;
  const trimmed = raw.trim();
  if (!trimmed) return null;
  if (trimmed.toLowerCase().startsWith("bearer ")) {
    return trimmed.slice(7).trim() || null;
  }
  return trimmed;
}

export async function getAuthenticatedUser(): Promise<
  { user: AuthenticatedUser } | { error: NextResponse }
> {
  const hdrs = await headers();
  const token =
    extractBearer(hdrs.get("authorization")) ??
    extractBearer(hdrs.get("x-supabase-access-token"));
  if (!token) return { error: unauthorized("missing bearer token") };

  let supaUser: Awaited<
    ReturnType<SupabaseClient["auth"]["getUser"]>
  >["data"]["user"];
  try {
    const { data, error } = await getSupabaseAdmin().auth.getUser(token);
    if (error || !data?.user) {
      return { error: unauthorized(error?.message ?? "no user for token") };
    }
    supaUser = data.user;
  } catch (err) {
    console.error("[child-auth] Supabase getUser threw:", err);
    return { error: unauthorized("supabase verification error") };
  }

  const email = supaUser.email ?? `${supaUser.id}@supabase.local`;
  const metadata = (supaUser.user_metadata ?? {}) as Record<string, unknown>;
  const name =
    (typeof metadata.full_name === "string" && metadata.full_name) ||
    (typeof metadata.name === "string" && metadata.name) ||
    (supaUser.email ? supaUser.email.split("@")[0] : "User");
  const emailVerified = Boolean(supaUser.email_confirmed_at);

  try {
    const dbUser = await resolveUser({
      supabaseId: supaUser.id,
      email,
      name,
      emailVerified,
    });

    return {
      user: {
        id: dbUser.id,
        email: dbUser.email,
        name: dbUser.name,
        role: dbUser.role,
      },
    };
  } catch (err) {
    console.error("[child-auth] user resolve failed:", err);
    return { error: unauthorized("user resolve failed") };
  }
}

async function resolveUser(params: {
  supabaseId: string;
  email: string;
  name: string;
  emailVerified: boolean;
}) {
  const { supabaseId, email, name, emailVerified } = params;

  const byId = await prisma.user.findUnique({ where: { id: supabaseId } });
  if (byId) {
    return prisma.user.update({
      where: { id: byId.id },
      data: { email, emailVerified },
    });
  }

  const byEmail = await prisma.user.findUnique({ where: { email } });
  if (byEmail) {
    return prisma.user.update({
      where: { id: byEmail.id },
      data: { emailVerified },
    });
  }

  try {
    return await prisma.user.create({
      data: {
        id: supabaseId,
        email,
        name,
        emailVerified,
        role: "user",
      },
    });
  } catch (err: unknown) {
    if (
      typeof err === "object" &&
      err !== null &&
      "code" in err &&
      (err as { code?: string }).code === "P2002"
    ) {
      const racing = await prisma.user.findUnique({ where: { email } });
      if (racing) return racing;
    }
    throw err;
  }
}

export async function validateChildAccess(childProfileId: string) {
  const result = await getAuthenticatedUser();
  if ("error" in result) return result;

  const childProfile = await prisma.child_profile.findFirst({
    where: { id: childProfileId, userId: result.user.id },
  });

  if (!childProfile) {
    return {
      error: NextResponse.json(
        { error: { code: "forbidden", message: "You do not have access to this child profile" } },
        { status: 403 }
      ),
    };
  }

  return { user: result.user, childProfile };
}

